 if(sr.conditionalSurvivalBounds){const cb=sr.conditionalSurvivalBounds;account.append(mk('p','Conditional printing ceiling: '+cb.maxApprox+' copies. '+cb.assumptions,'caption'));}
 const copies=(sr.evidence||[]).filter(e=>e.institution||e.callNumber||Number.isFinite(e.copies));
 if(copies.length){const details=mk('details'),summary=mk('summary','Inspect the documented copies'),list=mk('ul');
  copies.forEach(e=>{const li=mk('li');li.append(a(e.title+' ↗',e.url));if(e.callNumber)li.append(mk('span','Shelfmark / identifier: '+e.callNumber));if(Number.isFinite(e.copies))li.append(mk('span',e.copies+' documented '+(e.copies===1?'copy':'copies')));if(e.note)li.append(mk('p',e.note,'caption'));list.append(li)});details.append(summary,list);account.append(details);
 }
 if(w.researchExclusions?.length){const exclusions=mk('details');exclusions.append(mk('summary','Sources excluded from the copy count'));const list=mk('ul');w.researchExclusions.forEach(e=>{const li=mk('li');li.append(mk('p',e.reason));if(e.source)li.append(a('Inspect excluded reference ↗',e.source));list.append(li)});exclusions.append(list);account.append(exclusions)}survival.append(account);
